  passphrase: "PASSWORD",
  username: "USERNAME",
  "email address": "EMAIL",
  "phone number": "PHONE",
  "ip address": "IP",
  "location address": "ADDRESS",
  "date of birth": "DATE_OF_BIRTH",
  "government id number": "GOVERNMENT_ID",
  "passport number": "PASSPORT",
